"""Electronics and current electricity on the circuit engine
(lib/src/benches/electronics/): diodes, rectifiers, transistors, gates,
RC/LCR, op-amps, the 555, Kirchhoff, metre bridge and potentiometer."""


def add(lab, W, Q):
    # Apparatus shared by many labs.
    SUPPLY = W('Variable DC power supply (0–10 V)', 'परिवर्ती DC विद्युत आपूर्ति (0–10 V)', 'ಬದಲಾಯಿಸಬಹುದಾದ DC ವಿದ್ಯುತ್ ಪೂರೈಕೆ (0–10 V)')
    MA = W('Milliammeter (and microammeter)', 'मिलीऐमीटर (और माइक्रोऐमीटर)', 'ಮಿಲಿಅಮ್ಮೀಟರ್ (ಮತ್ತು ಮೈಕ್ರೋಅಮ್ಮೀಟರ್)')
    VM = W('Voltmeter', 'वोल्टमीटर', 'ವೋಲ್ಟ್‌ಮೀಟರ್')
    WIRES = W('Connecting wires and a breadboard', 'संयोजक तार और ब्रेडबोर्ड', 'ಸಂಪರ್ಕ ತಂತಿಗಳು ಮತ್ತು ಬ್ರೆಡ್‌ಬೋರ್ಡ್')
    RES = W('Series resistor (100 Ω) to limit the current', 'धारा सीमित करने के लिए श्रेणी प्रतिरोधक (100 Ω)', 'ಪ್ರವಾಹ ಮಿತಿಗೊಳಿಸಲು ಸರಣಿ ರೋಧಕ (100 Ω)')
    CRO = W('Cathode-ray oscilloscope (CRO)', 'कैथोड किरण दोलनदर्शी (CRO)', 'ಕ್ಯಾಥೋಡ್ ಕಿರಣ ಆಂದೋಲನದರ್ಶಕ (CRO)')
    TRANS = W('Step-down transformer (230 V to 6/9/12 V)', 'अपचायी ट्रांसफ़ॉर्मर (230 V से 6/9/12 V)', 'ಇಳಿಕೆ ಪರಿವರ್ತಕ (230 V ನಿಂದ 6/9/12 V)')
    KEY = W('Plug key', 'प्लग कुंजी', 'ಪ್ಲಗ್ ಕೀ')
    GALV = W('Galvanometer', 'गैल्वेनोमीटर', 'ಗ್ಯಾಲ್ವನೋಮೀಟರ್')
    RBOX = W('Resistance box', 'प्रतिरोध बॉक्स', 'ರೋಧ ಪೆಟ್ಟಿಗೆ')
    JOCKEY = W('Jockey', 'जॉकी (सर्पी संपर्क)', 'ಜಾಕಿ (ಸರಿಯುವ ಸಂಪರ್ಕ)')
    RHEO = W('Rheostat', 'धारा नियंत्रक (रिओस्टेट)', 'ರಿಯೋಸ್ಟಾಟ್')

    P_POLARITY = W('Connect meters with + to + and choose a range larger than the expected reading.', 'मीटर + से + जोड़ें और अपेक्षित पाठ्यांक से बड़ी परास चुनें।', 'ಮೀಟರ್‌ಗಳನ್ನು + ರಿಂದ + ಗೆ ಜೋಡಿಸಿ, ನಿರೀಕ್ಷಿತ ಓದಿಗಿಂತ ದೊಡ್ಡ ವ್ಯಾಪ್ತಿ ಆರಿಸಿ.')
    P_CURRENT = W('Never let the current exceed the rated value of the device; always keep the series resistor in the circuit.', 'धारा कभी भी युक्ति के निर्धारित मान से अधिक न होने दें; श्रेणी प्रतिरोधक सदा परिपथ में रखें।', 'ಪ್ರವಾಹ ಸಾಧನದ ನಿಗದಿತ ಮೌಲ್ಯವನ್ನು ಎಂದೂ ಮೀರಬಾರದು; ಸರಣಿ ರೋಧಕವನ್ನು ಯಾವಾಗಲೂ ಮಂಡಲದಲ್ಲಿಡಿ.')
    P_SWITCH_OFF = W('Switch off the supply when changing connections.', 'संयोजन बदलते समय आपूर्ति बंद कर दें।', 'ಸಂಪರ್ಕ ಬದಲಿಸುವಾಗ ಪೂರೈಕೆ ಆಫ್ ಮಾಡಿ.')

    # ------------------------------------------------------------ diodes
    lab(
        id='pn-junction-diode', bench='diode', setup={'device': 'si'}, subject='Electronics', domain='electronics', levels=[12, 'ug'],
        curricula=['cbse', 'ncert', 'ka-puc'], mode='guided',
        keywords=['semiconductor', 'semiconductor electronics', 'p-n junction', 'pn junction', 'diode', 'forward bias', 'reverse bias', 'knee voltage', 'characteristics'],
        title=W('I–V characteristics of a p-n junction diode', 'p-n संधि डायोड के I–V अभिलक्षण', 'p-n ಸಂಧಿ ಡಯೋಡ್‌ನ I–V ಲಕ್ಷಣಗಳು'),
        summary=W('Forward- and reverse-bias a silicon diode, record V and I, and find its knee voltage.',
                  'सिलिकॉन डायोड को अग्र और पश्च अभिनति दें, V और I लिखें और उसकी घुटना वोल्टता ज्ञात करें।',
                  'ಸಿಲಿಕಾನ್ ಡಯೋಡ್‌ಗೆ ಮುಮ್ಮುಖ ಮತ್ತು ಹಿಮ್ಮುಖ ಬಯಾಸ್ ನೀಡಿ, V ಮತ್ತು I ದಾಖಲಿಸಿ, ಅದರ ನೀ (ಮೊಣಕಾಲು) ವೋಲ್ಟೇಜ್ ಕಂಡುಹಿಡಿಯಿರಿ.'),
        aim=W('To draw the I–V characteristic curves of a p-n junction diode in forward and reverse bias.',
              'अग्र और पश्च अभिनति में p-n संधि डायोड के I–V अभिलक्षण वक्र खींचना।',
              'ಮುಮ್ಮುಖ ಮತ್ತು ಹಿಮ್ಮುಖ ಬಯಾಸ್‌ನಲ್ಲಿ p-n ಸಂಧಿ ಡಯೋಡ್‌ನ I–V ಲಕ್ಷಣ ವಕ್ರಗಳನ್ನು ಎಳೆಯುವುದು.'),
        principle=W('A p-n junction has a depletion layer with a barrier potential (about 0.7 V for silicon). In forward bias the barrier is lowered: almost no current flows until the applied voltage nears the barrier (the knee voltage), then the current rises steeply. In reverse bias the barrier grows and only a tiny current of minority carriers (microamperes) flows.',
                    'p-n संधि में एक ह्रासी परत होती है जिसका रोधिका विभव (सिलिकॉन के लिए लगभग 0.7 V) होता है। अग्र अभिनति में रोधिका घटती है: लगाई गई वोल्टता रोधिका के निकट (घुटना वोल्टता) आने तक लगभग कोई धारा नहीं बहती, फिर धारा तेज़ी से बढ़ती है। पश्च अभिनति में रोधिका बढ़ती है और केवल अल्पसंख्यक वाहकों की बहुत छोटी धारा (माइक्रोऐम्पियर) बहती है।',
                    'p-n ಸಂಧಿಯಲ್ಲಿ ಕ್ಷೀಣಿಸಿದ ಪದರವಿದ್ದು ಅದಕ್ಕೆ ತಡೆ ವಿಭವ (ಸಿಲಿಕಾನ್‌ಗೆ ಸುಮಾರು 0.7 V) ಇರುತ್ತದೆ. ಮುಮ್ಮುಖ ಬಯಾಸ್‌ನಲ್ಲಿ ತಡೆ ಕಡಿಮೆಯಾಗುತ್ತದೆ: ಅನ್ವಯಿಸಿದ ವೋಲ್ಟೇಜ್ ತಡೆಯ ಹತ್ತಿರ (ನೀ ವೋಲ್ಟೇಜ್) ಬರುವವರೆಗೆ ಬಹುತೇಕ ಪ್ರವಾಹವಿಲ್ಲ, ನಂತರ ಪ್ರವಾಹ ವೇಗವಾಗಿ ಏರುತ್ತದೆ. ಹಿಮ್ಮುಖ ಬಯಾಸ್‌ನಲ್ಲಿ ತಡೆ ಹೆಚ್ಚುತ್ತದೆ; ಅಲ್ಪಸಂಖ್ಯಾತ ವಾಹಕಗಳ ಅತಿ ಸಣ್ಣ ಪ್ರವಾಹ (ಮೈಕ್ರೋಆಂಪಿಯರ್) ಮಾತ್ರ ಹರಿಯುತ್ತದೆ.'),
        apparatus=[W('Silicon p-n junction diode', 'सिलिकॉन p-n संधि डायोड', 'ಸಿಲಿಕಾನ್ p-n ಸಂಧಿ ಡಯೋಡ್'), SUPPLY, RES, MA, VM, WIRES],
        steps=[W('Connect the diode in forward bias: p side (anode) to the + of the supply through the resistor and milliammeter; voltmeter across the diode.',
                 'डायोड को अग्र अभिनति में जोड़ें: p सिरा (ऐनोड) प्रतिरोधक और मिलीऐमीटर से होते हुए आपूर्ति के + से; वोल्टमीटर डायोड के सिरों पर।',
                 'ಡಯೋಡನ್ನು ಮುಮ್ಮುಖ ಬಯಾಸ್‌ನಲ್ಲಿ ಜೋಡಿಸಿ: p ಭಾಗ (ಆನೋಡ್) ರೋಧಕ ಮತ್ತು ಮಿಲಿಅಮ್ಮೀಟರ್ ಮೂಲಕ ಪೂರೈಕೆಯ + ಗೆ; ವೋಲ್ಟ್‌ಮೀಟರ್ ಡಯೋಡ್‌ಗೆ ಅಡ್ಡಲಾಗಿ.'),
               W('Raise the supply in small steps and record V and I each time. Take closer readings around 0.5–0.8 V.',
                 'आपूर्ति को छोटे चरणों में बढ़ाएँ और हर बार V और I लिखें। 0.5–0.8 V के आसपास पाठ्यांक पास-पास लें।',
                 'ಪೂರೈಕೆಯನ್ನು ಸಣ್ಣ ಹಂತಗಳಲ್ಲಿ ಹೆಚ್ಚಿಸಿ ಪ್ರತಿ ಬಾರಿ V ಮತ್ತು I ದಾಖಲಿಸಿ. 0.5–0.8 V ಸುತ್ತ ಹತ್ತಿರ ಹತ್ತಿರ ಓದುಗಳನ್ನು ತೆಗೆದುಕೊಳ್ಳಿ.'),
               W('Switch to reverse bias (and a microammeter). Raise the voltage and record V and I.',
                 'पश्च अभिनति पर बदलें (और माइक्रोऐमीटर लगाएँ)। वोल्टता बढ़ाकर V और I लिखें।',
                 'ಹಿಮ್ಮುಖ ಬಯಾಸ್‌ಗೆ ಬದಲಿಸಿ (ಮೈಕ್ರೋಅಮ್ಮೀಟರ್ ಬಳಸಿ). ವೋಲ್ಟೇಜ್ ಹೆಚ್ಚಿಸಿ V ಮತ್ತು I ದಾಖಲಿಸಿ.'),
               W('Plot I against V for both biases on one graph (reverse values negative).', 'दोनों अभिनतियों के लिए I और V का ग्राफ़ एक ही कागज़ पर बनाएँ (पश्च मान ऋणात्मक)।', 'ಎರಡೂ ಬಯಾಸ್‌ಗಳಿಗೆ I ಮತ್ತು V ನಕ್ಷೆಯನ್ನು ಒಂದೇ ಹಾಳೆಯಲ್ಲಿ ಎಳೆಯಿರಿ (ಹಿಮ್ಮುಖ ಮೌಲ್ಯಗಳು ಋಣ).'),
               W('Extend the straight, steep part of the forward curve down to the V axis: that is the knee voltage.', 'अग्र वक्र के सीधे, खड़े भाग को V अक्ष तक बढ़ाएँ: वही घुटना वोल्टता है।', 'ಮುಮ್ಮುಖ ವಕ್ರದ ನೇರ, ಕಡಿದಾದ ಭಾಗವನ್ನು V ಅಕ್ಷದವರೆಗೆ ವಿಸ್ತರಿಸಿ: ಅದೇ ನೀ ವೋಲ್ಟೇಜ್.')],
        precautions=[P_CURRENT, P_POLARITY, W('Use a microammeter in reverse bias: the current is very small.', 'पश्च अभिनति में माइक्रोऐमीटर लें: धारा बहुत छोटी होती है।', 'ಹಿಮ್ಮುಖ ಬಯಾಸ್‌ನಲ್ಲಿ ಮೈಕ್ರೋಅಮ್ಮೀಟರ್ ಬಳಸಿ: ಪ್ರವಾಹ ಅತಿ ಸಣ್ಣದು.')],
        conclusion=W('The diode conducts well only in forward bias, after the knee voltage (about 0.7 V for silicon); in reverse bias only microamperes flow. The diode is a one-way valve for current.',
                     'डायोड केवल अग्र अभिनति में, घुटना वोल्टता (सिलिकॉन के लिए लगभग 0.7 V) के बाद अच्छी तरह चालन करता है; पश्च अभिनति में केवल माइक्रोऐम्पियर बहते हैं। डायोड धारा के लिए एकदिशीय वाल्व है।',
                     'ಡಯೋಡ್ ಮುಮ್ಮುಖ ಬಯಾಸ್‌ನಲ್ಲಿ ಮಾತ್ರ, ನೀ ವೋಲ್ಟೇಜ್ (ಸಿಲಿಕಾನ್‌ಗೆ ಸುಮಾರು 0.7 V) ನಂತರ ಚೆನ್ನಾಗಿ ವಾಹಕವಾಗುತ್ತದೆ; ಹಿಮ್ಮುಖ ಬಯಾಸ್‌ನಲ್ಲಿ ಮೈಕ್ರೋಆಂಪಿಯರ್ ಮಾತ್ರ. ಡಯೋಡ್ ಪ್ರವಾಹಕ್ಕೆ ಏಕಮುಖ ಕವಾಟ.'),
        viva=[Q(W('What is the knee voltage of a germanium diode?', 'जर्मेनियम डायोड की घुटना वोल्टता कितनी होती है?', 'ಜರ್ಮೇನಿಯಂ ಡಯೋಡ್‌ನ ನೀ ವೋಲ್ಟೇಜ್ ಎಷ್ಟು?'), W('About 0.3 V.', 'लगभग 0.3 V.', 'ಸುಮಾರು 0.3 V.')),
              Q(W('Why does a small current flow in reverse bias?', 'पश्च अभिनति में छोटी धारा क्यों बहती है?', 'ಹಿಮ್ಮುಖ ಬಯಾಸ್‌ನಲ್ಲಿ ಸಣ್ಣ ಪ್ರವಾಹ ಏಕೆ ಹರಿಯುತ್ತದೆ?'),
                W('Minority carriers (electrons in p, holes in n) are swept across the junction by the field.', 'अल्पसंख्यक वाहक (p में इलेक्ट्रॉन, n में होल) क्षेत्र द्वारा संधि के पार धकेले जाते हैं।', 'ಅಲ್ಪಸಂಖ್ಯಾತ ವಾಹಕಗಳು (p ಯಲ್ಲಿ ಎಲೆಕ್ಟ್ರಾನ್, n ನಲ್ಲಿ ರಂಧ್ರ) ಕ್ಷೇತ್ರದಿಂದ ಸಂಧಿಯ ಆಚೆ ತಳ್ಳಲ್ಪಡುತ್ತವೆ.')),
              Q(W('What is the dynamic resistance of a diode?', 'डायोड का गतिक प्रतिरोध क्या है?', 'ಡಯೋಡ್‌ನ ಚಲನಶೀಲ ರೋಧ ಎಂದರೇನು?'),
                W('ΔV ÷ ΔI at a point on the curve: small in forward bias above the knee.', 'वक्र के किसी बिंदु पर ΔV ÷ ΔI: घुटने के ऊपर अग्र अभिनति में यह छोटा होता है।', 'ವಕ್ರದ ಒಂದು ಬಿಂದುವಿನಲ್ಲಿ ΔV ÷ ΔI: ನೀ ಮೇಲೆ ಮುಮ್ಮುಖ ಬಯಾಸ್‌ನಲ್ಲಿ ಇದು ಸಣ್ಣದು.')),
              Q(W('Which side of the diode is marked by the band?', 'डायोड पर पट्टी किस सिरे को दर्शाती है?', 'ಡಯೋಡ್ ಮೇಲಿನ ಪಟ್ಟಿ ಯಾವ ತುದಿಯನ್ನು ಸೂಚಿಸುತ್ತದೆ?'),
                W('The cathode (n side).', 'कैथोड (n सिरा)।', 'ಕ್ಯಾಥೋಡ್ (n ಭಾಗ).'))],
    )

    lab(
        id='zener-diode', bench='diode', setup={'device': 'zener', 'bias': 'rev'}, subject='Electronics', domain='electronics', levels=[12, 'ug'],
        curricula=['cbse', 'ncert', 'ka-puc'],
        keywords=['zener', 'zener diode', 'breakdown', 'voltage regulator', 'reverse breakdown', 'semiconductor electronics'],
        title=W('Characteristics of a Zener diode', 'ज़ेनर डायोड के अभिलक्षण', 'ಜೀನರ್ ಡಯೋಡ್‌ನ ಲಕ್ಷಣಗಳು'),
        summary=W('Reverse-bias a Zener diode and find the voltage at which it breaks down and holds steady.',
                  'ज़ेनर डायोड को पश्च अभिनति दें और वह वोल्टता ज्ञात करें जिस पर यह भंजित होकर स्थिर रहता है।',
                  'ಜೀನರ್ ಡಯೋಡ್‌ಗೆ ಹಿಮ್ಮುಖ ಬಯಾಸ್ ನೀಡಿ, ಅದು ಭಂಜನಗೊಂಡು ಸ್ಥಿರವಾಗುವ ವೋಲ್ಟೇಜ್ ಕಂಡುಹಿಡಿಯಿರಿ.'),
        aim=W('To draw the reverse characteristic of a Zener diode and find its breakdown voltage.',
              'ज़ेनर डायोड का पश्च अभिलक्षण खींचना और उसकी भंजन वोल्टता ज्ञात करना।',
              'ಜೀನರ್ ಡಯೋಡ್‌ನ ಹಿಮ್ಮುಖ ಲಕ್ಷಣ ಎಳೆದು ಅದರ ಭಂಜನ ವೋಲ್ಟೇಜ್ ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('A Zener diode is heavily doped, so its depletion layer is thin. At a definite reverse voltage Vz the field breaks covalent bonds and the reverse current rises sharply while the voltage stays almost constant. This is why a Zener is used as a voltage regulator.',
                    'ज़ेनर डायोड भारी मादित होता है, इसलिए उसकी ह्रासी परत पतली होती है। एक निश्चित पश्च वोल्टता Vz पर क्षेत्र सहसंयोजी बंधों को तोड़ देता है और पश्च धारा तेज़ी से बढ़ती है जबकि वोल्टता लगभग स्थिर रहती है। इसीलिए ज़ेनर को वोल्टता नियंत्रक के रूप में प्रयोग करते हैं।',
                    'ಜೀನರ್ ಡಯೋಡ್ ಹೆಚ್ಚು ಡೋಪ್ ಮಾಡಿದ್ದು, ಅದರ ಕ್ಷೀಣ ಪದರ ತೆಳು. ಒಂದು ನಿರ್ದಿಷ್ಟ ಹಿಮ್ಮುಖ ವೋಲ್ಟೇಜ್ Vz ನಲ್ಲಿ ಕ್ಷೇತ್ರವು ಸಹವೇಲೆನ್ಸೀಯ ಬಂಧಗಳನ್ನು ಮುರಿಯುತ್ತದೆ; ಹಿಮ್ಮುಖ ಪ್ರವಾಹ ವೇಗವಾಗಿ ಏರುತ್ತದೆ, ವೋಲ್ಟೇಜ್ ಬಹುತೇಕ ಸ್ಥಿರ. ಆದ್ದರಿಂದ ಜೀನರನ್ನು ವೋಲ್ಟೇಜ್ ನಿಯಂತ್ರಕವಾಗಿ ಬಳಸುತ್ತಾರೆ.'),
        apparatus=[W('Zener diode (3.3, 5.1 or 6.2 V)', 'ज़ेनर डायोड (3.3, 5.1 या 6.2 V)', 'ಜೀನರ್ ಡಯೋಡ್ (3.3, 5.1 ಅಥವಾ 6.2 V)'), SUPPLY, RES, MA, VM, WIRES],
        steps=[W('Connect the Zener in reverse bias: its cathode (band) towards the + of the supply, through the resistor and milliammeter.', 'ज़ेनर को पश्च अभिनति में जोड़ें: उसका कैथोड (पट्टी) प्रतिरोधक और मिलीऐमीटर से होते हुए आपूर्ति के + की ओर।', 'ಜೀನರನ್ನು ಹಿಮ್ಮುಖ ಬಯಾಸ್‌ನಲ್ಲಿ ಜೋಡಿಸಿ: ಅದರ ಕ್ಯಾಥೋಡ್ (ಪಟ್ಟಿ) ರೋಧಕ ಮತ್ತು ಮಿಲಿಅಮ್ಮೀಟರ್ ಮೂಲಕ ಪೂರೈಕೆಯ + ಕಡೆಗೆ.'),
               W('Raise the supply slowly from zero and record the voltage across the Zener and the current.', 'आपूर्ति को शून्य से धीरे-धीरे बढ़ाएँ और ज़ेनर के सिरों की वोल्टता तथा धारा लिखें।', 'ಪೂರೈಕೆಯನ್ನು ಶೂನ್ಯದಿಂದ ನಿಧಾನವಾಗಿ ಹೆಚ್ಚಿಸಿ, ಜೀನರ್‌ಗೆ ಅಡ್ಡ ವೋಲ್ಟೇಜ್ ಮತ್ತು ಪ್ರವಾಹ ದಾಖಲಿಸಿ.'),
               W('Near breakdown take readings in small steps; above it, note how little the voltage changes while the current grows.', 'भंजन के पास छोटे चरणों में पाठ्यांक लें; उसके ऊपर देखें कि धारा बढ़ने पर वोल्टता कितनी कम बदलती है।', 'ಭಂಜನದ ಹತ್ತಿರ ಸಣ್ಣ ಹಂತಗಳಲ್ಲಿ ಓದು ತೆಗೆದುಕೊಳ್ಳಿ; ಅದರ ಮೇಲೆ ಪ್ರವಾಹ ಹೆಚ್ಚಿದರೂ ವೋಲ್ಟೇಜ್ ಎಷ್ಟು ಕಡಿಮೆ ಬದಲಾಗುತ್ತದೆ ಗಮನಿಸಿ.'),
               W('Also take a few forward-bias readings.', 'कुछ अग्र अभिनति पाठ्यांक भी लें।', 'ಕೆಲವು ಮುಮ್ಮುಖ ಬಯಾಸ್ ಓದುಗಳನ್ನೂ ತೆಗೆದುಕೊಳ್ಳಿ.'),
               W('Plot I against V and read the breakdown voltage Vz where the reverse curve turns steeply down.', 'I और V का ग्राफ़ बनाएँ और भंजन वोल्टता Vz वहाँ पढ़ें जहाँ पश्च वक्र तेज़ी से नीचे मुड़ता है।', 'I ಮತ್ತು V ನಕ್ಷೆ ಎಳೆದು, ಹಿಮ್ಮುಖ ವಕ್ರ ಕಡಿದಾಗಿ ಕೆಳಗೆ ತಿರುಗುವಲ್ಲಿ ಭಂಜನ ವೋಲ್ಟೇಜ್ Vz ಓದಿ.')],
        precautions=[P_CURRENT, W('Keep the Zener current below its rated maximum (power = Vz × I).', 'ज़ेनर धारा को उसकी अधिकतम सीमा से नीचे रखें (शक्ति = Vz × I)।', 'ಜೀನರ್ ಪ್ರವಾಹವನ್ನು ಅದರ ಗರಿಷ್ಠ ಮಿತಿಗಿಂತ ಕಡಿಮೆ ಇಡಿ (ಶಕ್ತಿ = Vz × I).'), P_POLARITY],
        conclusion=W('In reverse bias the Zener current stays tiny up to Vz; beyond it the current rises sharply at an almost constant voltage, so the Zener can hold a load voltage steady.',
                     'पश्च अभिनति में Vz तक ज़ेनर धारा बहुत छोटी रहती है; उसके बाद लगभग स्थिर वोल्टता पर धारा तेज़ी से बढ़ती है, इसलिए ज़ेनर लोड वोल्टता को स्थिर रख सकता है।',
                     'ಹಿಮ್ಮುಖ ಬಯಾಸ್‌ನಲ್ಲಿ Vz ವರೆಗೆ ಜೀನರ್ ಪ್ರವಾಹ ಅತಿ ಸಣ್ಣ; ಅದರ ಆಚೆ ಬಹುತೇಕ ಸ್ಥಿರ ವೋಲ್ಟೇಜ್‌ನಲ್ಲಿ ಪ್ರವಾಹ ವೇಗವಾಗಿ ಏರುತ್ತದೆ, ಆದ್ದರಿಂದ ಜೀನರ್ ಲೋಡ್ ವೋಲ್ಟೇಜನ್ನು ಸ್ಥಿರವಾಗಿಡಬಲ್ಲದು.'),
        viva=[Q(W('How is a Zener diode different from an ordinary diode?', 'ज़ेनर डायोड साधारण डायोड से कैसे भिन्न है?', 'ಜೀನರ್ ಡಯೋಡ್ ಸಾಮಾನ್ಯ ಡಯೋಡ್‌ಗಿಂತ ಹೇಗೆ ಭಿನ್ನ?'),
                W('It is heavily doped and designed to work safely in reverse breakdown.', 'यह भारी मादित होता है और पश्च भंजन में सुरक्षित काम करने के लिए बना है।', 'ಅದು ಹೆಚ್ಚು ಡೋಪ್ ಮಾಡಲ್ಪಟ್ಟಿದ್ದು ಹಿಮ್ಮುಖ ಭಂಜನದಲ್ಲಿ ಸುರಕ್ಷಿತವಾಗಿ ಕೆಲಸ ಮಾಡಲು ವಿನ್ಯಾಸಗೊಂಡಿದೆ.')),
              Q(W('How is a Zener connected as a voltage regulator?', 'वोल्टता नियंत्रक के रूप में ज़ेनर कैसे जोड़ा जाता है?', 'ವೋಲ್ಟೇಜ್ ನಿಯಂತ್ರಕವಾಗಿ ಜೀನರನ್ನು ಹೇಗೆ ಜೋಡಿಸುತ್ತಾರೆ?'),
                W('In reverse bias, in parallel with the load, with a series resistor from the supply.', 'पश्च अभिनति में, लोड के समानांतर, आपूर्ति से एक श्रेणी प्रतिरोधक के साथ।', 'ಹಿಮ್ಮುಖ ಬಯಾಸ್‌ನಲ್ಲಿ, ಲೋಡ್‌ಗೆ ಸಮಾಂತರವಾಗಿ, ಪೂರೈಕೆಯಿಂದ ಸರಣಿ ರೋಧಕದೊಂದಿಗೆ.')),
              Q(W('What is the dynamic resistance of a Zener after breakdown?', 'भंजन के बाद ज़ेनर का गतिक प्रतिरोध कैसा होता है?', 'ಭಂಜನದ ನಂತರ ಜೀನರ್‌ನ ಚಲನಶೀಲ ರೋಧ ಹೇಗಿರುತ್ತದೆ?'),
                W('Very small: a large change of current makes only a small change of voltage.', 'बहुत छोटा: धारा के बड़े परिवर्तन से वोल्टता में बहुत कम परिवर्तन होता है।', 'ಅತಿ ಸಣ್ಣ: ಪ್ರವಾಹದ ದೊಡ್ಡ ಬದಲಾವಣೆ ವೋಲ್ಟೇಜ್‌ನಲ್ಲಿ ಸ್ವಲ್ಪವೇ ಬದಲಾವಣೆ ತರುತ್ತದೆ.'))],
    )

    lab(
        id='led-characteristics', bench='diode', setup={'device': 'led'}, subject='Electronics', domain='electronics', levels=[12, 'ug'],
        curricula=['cbse', 'ka-puc'],
        keywords=['led', 'light emitting diode', 'optoelectronic devices', 'band gap', 'semiconductor electronics'],
        title=W('I–V characteristics of LEDs', 'LED के I–V अभिलक्षण', 'LED ಗಳ I–V ಲಕ್ಷಣಗಳು'),
        summary=W('Compare red, yellow, green and blue LEDs: each switches on at a different voltage.',
                  'लाल, पीले, हरे और नीले LED की तुलना करें: हर एक अलग वोल्टता पर जलता है।',
                  'ಕೆಂಪು, ಹಳದಿ, ಹಸಿರು ಮತ್ತು ನೀಲಿ LED ಗಳನ್ನು ಹೋಲಿಸಿ: ಪ್ರತಿಯೊಂದೂ ಬೇರೆ ವೋಲ್ಟೇಜ್‌ನಲ್ಲಿ ಬೆಳಗುತ್ತದೆ.'),
        aim=W('To draw the forward I–V characteristics of LEDs of different colours and relate the turn-on voltage to the colour.',
              'विभिन्न रंगों के LED के अग्र I–V अभिलक्षण खींचना और चालू होने की वोल्टता का रंग से संबंध देखना।',
              'ಬೇರೆ ಬೇರೆ ಬಣ್ಣಗಳ LED ಗಳ ಮುಮ್ಮುಖ I–V ಲಕ್ಷಣಗಳನ್ನು ಎಳೆದು, ಆರಂಭ ವೋಲ್ಟೇಜನ್ನು ಬಣ್ಣದೊಂದಿಗೆ ಸಂಬಂಧಿಸುವುದು.'),
        principle=W('In an LED, electrons and holes recombine at the junction and give out photons of energy close to the band gap, E = hc/λ. Light of shorter wavelength (blue) needs a larger band gap, so a blue LED switches on at a higher voltage (about 2.6 V) than a red one (about 1.9 V).',
                    'LED में इलेक्ट्रॉन और होल संधि पर पुनर्संयोजित होकर बैंड अंतराल के निकट ऊर्जा के फ़ोटॉन देते हैं, E = hc/λ. छोटी तरंगदैर्घ्य (नीला) के प्रकाश के लिए बड़ा बैंड अंतराल चाहिए, इसलिए नीला LED लाल (लगभग 1.9 V) से अधिक वोल्टता (लगभग 2.6 V) पर जलता है।',
                    'LED ಯಲ್ಲಿ ಎಲೆಕ್ಟ್ರಾನ್ ಮತ್ತು ರಂಧ್ರಗಳು ಸಂಧಿಯಲ್ಲಿ ಮರುಸಂಯೋಗಗೊಂಡು ಬ್ಯಾಂಡ್ ಅಂತರದ ಹತ್ತಿರದ ಶಕ್ತಿಯ ಫೋಟಾನ್‌ಗಳನ್ನು ನೀಡುತ್ತವೆ, E = hc/λ. ಕಡಿಮೆ ತರಂಗಾಂತರದ (ನೀಲಿ) ಬೆಳಕಿಗೆ ದೊಡ್ಡ ಬ್ಯಾಂಡ್ ಅಂತರ ಬೇಕು; ಆದ್ದರಿಂದ ನೀಲಿ LED ಕೆಂಪಿಗಿಂತ (ಸುಮಾರು 1.9 V) ಹೆಚ್ಚು ವೋಲ್ಟೇಜ್‌ನಲ್ಲಿ (ಸುಮಾರು 2.6 V) ಬೆಳಗುತ್ತದೆ.'),
        apparatus=[W('Red, yellow, green and blue LEDs', 'लाल, पीले, हरे और नीले LED', 'ಕೆಂಪು, ಹಳದಿ, ಹಸಿರು ಮತ್ತು ನೀಲಿ LED ಗಳು'), SUPPLY, RES, MA, VM, WIRES],
        steps=[W('Connect the red LED in forward bias (long leg to +) with the resistor and milliammeter; voltmeter across the LED.', 'लाल LED को अग्र अभिनति में (लंबी टाँग + से) प्रतिरोधक और मिलीऐमीटर के साथ जोड़ें; वोल्टमीटर LED के सिरों पर।', 'ಕೆಂಪು LED ಯನ್ನು ಮುಮ್ಮುಖ ಬಯಾಸ್‌ನಲ್ಲಿ (ಉದ್ದ ಕಾಲು + ಗೆ) ರೋಧಕ ಮತ್ತು ಮಿಲಿಅಮ್ಮೀಟರ್ ಜೊತೆ ಜೋಡಿಸಿ; ವೋಲ್ಟ್‌ಮೀಟರ್ LED ಗೆ ಅಡ್ಡಲಾಗಿ.'),
               W('Raise the supply in steps and record V and I; note when the LED starts to glow.', 'आपूर्ति चरणों में बढ़ाएँ और V तथा I लिखें; देखें कि LED कब चमकने लगता है।', 'ಪೂರೈಕೆಯನ್ನು ಹಂತಗಳಲ್ಲಿ ಹೆಚ್ಚಿಸಿ V ಮತ್ತು I ದಾಖಲಿಸಿ; LED ಯಾವಾಗ ಹೊಳೆಯಲು ಆರಂಭಿಸುತ್ತದೆ ಗಮನಿಸಿ.'),
               W('Repeat for the yellow, green and blue LEDs.', 'पीले, हरे और नीले LED के लिए दोहराएँ।', 'ಹಳದಿ, ಹಸಿರು ಮತ್ತು ನೀಲಿ LED ಗಳಿಗೆ ಪುನರಾವರ್ತಿಸಿ.'),
               W('Plot all four curves and compare their knee voltages with hc/λe.', 'चारों वक्र बनाएँ और उनकी घुटना वोल्टताओं की तुलना hc/λe से करें।', 'ನಾಲ್ಕೂ ವಕ್ರಗಳನ್ನು ಎಳೆದು ಅವುಗಳ ನೀ ವೋಲ್ಟೇಜ್‌ಗಳನ್ನು hc/λe ಯೊಂದಿಗೆ ಹೋಲಿಸಿ.')],
        precautions=[P_CURRENT, W('Do not look straight into a bright LED for long.', 'तेज़ चमकते LED में देर तक सीधे न देखें।', 'ಪ್ರಕಾಶಮಾನ LED ಯೊಳಗೆ ಹೆಚ್ಚು ಹೊತ್ತು ನೇರವಾಗಿ ನೋಡಬೇಡಿ.'), W('An LED breaks down at a small reverse voltage (about 5 V): do not reverse-bias it far.', 'LED छोटी पश्च वोल्टता (लगभग 5 V) पर ही भंजित हो जाता है: उसे अधिक पश्च अभिनति न दें।', 'LED ಸಣ್ಣ ಹಿಮ್ಮುಖ ವೋಲ್ಟೇಜ್‌ನಲ್ಲೇ (ಸುಮಾರು 5 V) ಭಂಜನಗೊಳ್ಳುತ್ತದೆ: ಹೆಚ್ಚು ಹಿಮ್ಮುಖ ಬಯಾಸ್ ನೀಡಬೇಡಿ.')],
        conclusion=W('Each LED conducts and glows only above its knee voltage, and the knee voltage increases from red to blue as the photon energy hc/λ increases.',
                     'हर LED अपनी घुटना वोल्टता के ऊपर ही चालन करता और चमकता है, और फ़ोटॉन ऊर्जा hc/λ बढ़ने के साथ घुटना वोल्टता लाल से नीले की ओर बढ़ती है।',
                     'ಪ್ರತಿ LED ತನ್ನ ನೀ ವೋಲ್ಟೇಜ್ ಮೇಲೆ ಮಾತ್ರ ವಾಹಕವಾಗಿ ಹೊಳೆಯುತ್ತದೆ; ಫೋಟಾನ್ ಶಕ್ತಿ hc/λ ಹೆಚ್ಚಿದಂತೆ ನೀ ವೋಲ್ಟೇಜ್ ಕೆಂಪಿನಿಂದ ನೀಲಿಯತ್ತ ಹೆಚ್ಚುತ್ತದೆ.'),
        viva=[Q(W('Why does a blue LED need more voltage than a red one?', 'नीले LED को लाल से अधिक वोल्टता क्यों चाहिए?', 'ನೀಲಿ LED ಗೆ ಕೆಂಪಿಗಿಂತ ಹೆಚ್ಚು ವೋಲ್ಟೇಜ್ ಏಕೆ ಬೇಕು?'),
                W('Blue photons have more energy (shorter wavelength), so the band gap is larger.', 'नीले फ़ोटॉन की ऊर्जा अधिक (तरंगदैर्घ्य छोटी) है, इसलिए बैंड अंतराल बड़ा है।', 'ನೀಲಿ ಫೋಟಾನ್‌ಗಳಿಗೆ ಹೆಚ್ಚು ಶಕ್ತಿ (ಕಡಿಮೆ ತರಂಗಾಂತರ), ಆದ್ದರಿಂದ ಬ್ಯಾಂಡ್ ಅಂತರ ದೊಡ್ಡದು.')),
              Q(W('Why are LEDs not made of silicon?', 'LED सिलिकॉन से क्यों नहीं बनाए जाते?', 'LED ಗಳನ್ನು ಸಿಲಿಕಾನ್‌ನಿಂದ ಏಕೆ ಮಾಡುವುದಿಲ್ಲ?'),
                W('Silicon has an indirect band gap and gives out heat rather than light; compounds like GaAsP and InGaN are used.', 'सिलिकॉन का बैंड अंतराल अप्रत्यक्ष है और यह प्रकाश की जगह ऊष्मा देता है; GaAsP और InGaN जैसे यौगिक प्रयोग होते हैं।', 'ಸಿಲಿಕಾನ್‌ನ ಬ್ಯಾಂಡ್ ಅಂತರ ಪರೋಕ್ಷ; ಅದು ಬೆಳಕಿಗಿಂತ ಉಷ್ಣ ನೀಡುತ್ತದೆ; GaAsP, InGaN ನಂತಹ ಸಂಯುಕ್ತಗಳನ್ನು ಬಳಸುತ್ತಾರೆ.')),
              Q(W('Why is a resistor always used with an LED?', 'LED के साथ सदा प्रतिरोधक क्यों लगाया जाता है?', 'LED ಜೊತೆ ಯಾವಾಗಲೂ ರೋಧಕ ಏಕೆ ಬಳಸುತ್ತಾರೆ?'),
                W('Above the knee the current rises very steeply; the resistor limits it.', 'घुटने के ऊपर धारा बहुत तेज़ी से बढ़ती है; प्रतिरोधक उसे सीमित करता है।', 'ನೀ ಮೇಲೆ ಪ್ರವಾಹ ಅತಿ ವೇಗವಾಗಿ ಏರುತ್ತದೆ; ರೋಧಕ ಅದನ್ನು ಮಿತಿಗೊಳಿಸುತ್ತದೆ.'))],
    )

    lab(
        id='planck-constant-led', bench='planck', subject='Physics', domain='physics', levels=['ug'], curricula=['ug-physics'],
        keywords=["planck's constant", 'planck constant', 'led', 'photon energy', 'quantum', 'modern physics'],
        title=W("Planck's constant using LEDs", 'LED से प्लांक नियतांक', 'LED ಗಳಿಂದ ಪ್ಲಾಂಕ್ ಸ್ಥಿರಾಂಕ'),
        summary=W('Find the voltage at which LEDs of four colours just glow, and get h from the slope of V against 1/λ.',
                  'चार रंगों के LED जिस वोल्टता पर बस चमकने लगते हैं वह ज्ञात करें, और V तथा 1/λ के ग्राफ़ की प्रवणता से h निकालें।',
                  'ನಾಲ್ಕು ಬಣ್ಣಗಳ LED ಗಳು ಕೇವಲ ಹೊಳೆಯಲಾರಂಭಿಸುವ ವೋಲ್ಟೇಜ್ ಕಂಡುಹಿಡಿದು, V ಮತ್ತು 1/λ ನಕ್ಷೆಯ ಇಳಿಜಾರಿನಿಂದ h ಪಡೆಯಿರಿ.'),
        aim=W("To determine Planck's constant from the threshold voltages of LEDs of known wavelengths.",
              'ज्ञात तरंगदैर्घ्य वाले LED की देहली वोल्टताओं से प्लांक नियतांक ज्ञात करना।',
              'ತಿಳಿದ ತರಂಗಾಂತರದ LED ಗಳ ಹೊಸ್ತಿಲು ವೋಲ್ಟೇಜ್‌ಗಳಿಂದ ಪ್ಲಾಂಕ್ ಸ್ಥಿರಾಂಕ ನಿರ್ಧರಿಸುವುದು.'),
        principle=W('An LED starts to emit when the energy eV given to each electron equals the photon energy: eV = hc/λ. So V = (hc/e)(1/λ): a graph of the threshold voltage against 1/λ is a straight line of slope hc/e, and h = e × slope ÷ c. A small constant offset (the "just glowing" judgement) shifts the intercept but not the slope.',
                    'LED उत्सर्जन तब शुरू करता है जब हर इलेक्ट्रॉन को दी गई ऊर्जा eV फ़ोटॉन ऊर्जा के बराबर हो: eV = hc/λ. इसलिए V = (hc/e)(1/λ): देहली वोल्टता और 1/λ का ग्राफ़ hc/e प्रवणता की सीधी रेखा है, और h = e × प्रवणता ÷ c. एक छोटा स्थिर अंतर ("बस चमकना" का अनुमान) अंतःखंड बदलता है, प्रवणता नहीं।',
                    'ಪ್ರತಿ ಎಲೆಕ್ಟ್ರಾನ್‌ಗೆ ನೀಡಿದ ಶಕ್ತಿ eV ಫೋಟಾನ್ ಶಕ್ತಿಗೆ ಸಮವಾದಾಗ LED ಹೊರಸೂಸಲು ಆರಂಭಿಸುತ್ತದೆ: eV = hc/λ. ಆದ್ದರಿಂದ V = (hc/e)(1/λ): ಹೊಸ್ತಿಲು ವೋಲ್ಟೇಜ್ ಮತ್ತು 1/λ ನಕ್ಷೆ hc/e ಇಳಿಜಾರಿನ ಸರಳರೇಖೆ; h = e × ಇಳಿಜಾರು ÷ c. ಸಣ್ಣ ಸ್ಥಿರ ವ್ಯತ್ಯಾಸ ("ಕೇವಲ ಹೊಳೆಯುವಿಕೆ" ಅಂದಾಜು) ಅಂತಃಖಂಡವನ್ನು ಬದಲಿಸುತ್ತದೆ, ಇಳಿಜಾರನ್ನಲ್ಲ.'),
        apparatus=[W('LEDs of known wavelength (625, 590, 525, 470 nm)', 'ज्ञात तरंगदैर्घ्य वाले LED (625, 590, 525, 470 nm)', 'ತಿಳಿದ ತರಂಗಾಂತರದ LED ಗಳು (625, 590, 525, 470 nm)'),
                   W('DC supply with fine control (0–3.5 V)', 'सूक्ष्म नियंत्रण वाली DC आपूर्ति (0–3.5 V)', 'ಸೂಕ್ಷ್ಮ ನಿಯಂತ್ರಣದ DC ಪೂರೈಕೆ (0–3.5 V)'), RES, MA, W('Digital voltmeter', 'अंकीय वोल्टमीटर', 'ಡಿಜಿಟಲ್ ವೋಲ್ಟ್‌ಮೀಟರ್'),
                   W('A dark box or tube to view the LED', 'LED देखने के लिए अँधेरा बॉक्स या नली', 'LED ನೋಡಲು ಕತ್ತಲ ಪೆಟ್ಟಿಗೆ ಅಥವಾ ಕೊಳವೆ')],
        steps=[W('Connect the first LED in forward bias through the resistor; put the voltmeter across the LED.', 'पहले LED को प्रतिरोधक के साथ अग्र अभिनति में जोड़ें; वोल्टमीटर LED के सिरों पर लगाएँ।', 'ಮೊದಲ LED ಯನ್ನು ರೋಧಕದ ಜೊತೆ ಮುಮ್ಮುಖ ಬಯಾಸ್‌ನಲ್ಲಿ ಜೋಡಿಸಿ; ವೋಲ್ಟ್‌ಮೀಟರ್ LED ಗೆ ಅಡ್ಡಲಾಗಿ.'),
               W('Looking into the dark box, raise the voltage very slowly until the LED just begins to glow. Record that voltage.', 'अँधेरे बॉक्स में देखते हुए वोल्टता बहुत धीरे बढ़ाएँ जब तक LED बस चमकने न लगे। वह वोल्टता लिखें।', 'ಕತ್ತಲ ಪೆಟ್ಟಿಗೆಯೊಳಗೆ ನೋಡುತ್ತಾ LED ಕೇವಲ ಹೊಳೆಯಲಾರಂಭಿಸುವವರೆಗೆ ವೋಲ್ಟೇಜನ್ನು ತುಂಬ ನಿಧಾನವಾಗಿ ಹೆಚ್ಚಿಸಿ. ಆ ವೋಲ್ಟೇಜ್ ದಾಖಲಿಸಿ.'),
               W('Repeat two or three times for each colour and take the mean.', 'हर रंग के लिए दो-तीन बार दोहराएँ और माध्य लें।', 'ಪ್ರತಿ ಬಣ್ಣಕ್ಕೆ ಎರಡು-ಮೂರು ಬಾರಿ ಪುನರಾವರ್ತಿಸಿ ಸರಾಸರಿ ತೆಗೆಯಿರಿ.'),
               W('Plot the threshold voltage against 1/λ and draw the best straight line.', 'देहली वोल्टता और 1/λ का ग्राफ़ बनाकर सर्वोत्तम सीधी रेखा खींचें।', 'ಹೊಸ್ತಿಲು ವೋಲ್ಟೇಜ್ ಮತ್ತು 1/λ ನಕ್ಷೆ ಎಳೆದು ಉತ್ತಮ ಸರಳರೇಖೆ ಎಳೆಯಿರಿ.'),
               W('Find the slope and its uncertainty, then h = e × slope ÷ c.', 'प्रवणता और उसकी अनिश्चितता ज्ञात करें, फिर h = e × प्रवणता ÷ c.', 'ಇಳಿಜಾರು ಮತ್ತು ಅದರ ಅನಿಶ್ಚಿತತೆ ಕಂಡುಹಿಡಿದು, h = e × ಇಳಿಜಾರು ÷ c.'),
               W('Export the readings as CSV for your record book.', 'अपनी रिकॉर्ड पुस्तिका के लिए पाठ्यांक CSV में निर्यात करें।', 'ನಿಮ್ಮ ದಾಖಲೆ ಪುಸ್ತಕಕ್ಕಾಗಿ ಓದುಗಳನ್ನು CSV ಆಗಿ ರಫ್ತು ಮಾಡಿ.')],
        precautions=[W('Judge "just glowing" the same way for every LED, in the dark.', '"बस चमकना" हर LED के लिए अँधेरे में एक ही तरह आँकें।', '"ಕೇವಲ ಹೊಳೆಯುವಿಕೆ"ಯನ್ನು ಪ್ರತಿ LED ಗೆ ಕತ್ತಲಲ್ಲಿ ಒಂದೇ ರೀತಿ ನಿರ್ಣಯಿಸಿ.'), P_CURRENT,
                     W("Use the manufacturer's peak wavelength for each LED.", 'हर LED के लिए निर्माता द्वारा दी गई शिखर तरंगदैर्घ्य लें।', 'ಪ್ರತಿ LED ಗೆ ತಯಾರಕರ ಶಿಖರ ತರಂಗಾಂತರ ಬಳಸಿ.')],
        conclusion=W('The threshold voltage is proportional to 1/λ, and the slope gives Planck’s constant close to 6.63 × 10⁻³⁴ J s, within the uncertainty of the fit.',
                     'देहली वोल्टता 1/λ के अनुक्रमानुपाती है, और प्रवणता से प्लांक नियतांक 6.63 × 10⁻³⁴ J s के निकट, फ़िट की अनिश्चितता के भीतर, मिलता है।',
                     'ಹೊಸ್ತಿಲು ವೋಲ್ಟೇಜ್ 1/λ ಗೆ ಅನುಪಾತೀಯ; ಇಳಿಜಾರು ಪ್ಲಾಂಕ್ ಸ್ಥಿರಾಂಕವನ್ನು 6.63 × 10⁻³⁴ J s ಹತ್ತಿರ, ಹೊಂದಿಕೆಯ ಅನಿಶ್ಚಿತತೆಯೊಳಗೆ ನೀಡುತ್ತದೆ.'),
        viva=[Q(W('What are the units of Planck’s constant?', 'प्लांक नियतांक की इकाई क्या है?', 'ಪ್ಲಾಂಕ್ ಸ್ಥಿರಾಂಕದ ಏಕಮಾನ ಯಾವುದು?'), W('Joule second (J s).', 'जूल सेकंड (J s).', 'ಜೂಲ್ ಸೆಕೆಂಡ್ (J s).')),
              Q(W('Why do we use the slope and not one LED’s voltage?', 'हम एक LED की वोल्टता के बजाय प्रवणता क्यों लेते हैं?', 'ಒಂದು LED ಯ ವೋಲ್ಟೇಜ್ ಬದಲು ಇಳಿಜಾರನ್ನು ಏಕೆ ಬಳಸುತ್ತೇವೆ?'),
                W('A constant error in judging the threshold cancels out of the slope.', 'देहली के अनुमान में स्थिर त्रुटि प्रवणता में से कट जाती है।', 'ಹೊಸ್ತಿಲು ಅಂದಾಜಿನ ಸ್ಥಿರ ದೋಷ ಇಳಿಜಾರಿನಲ್ಲಿ ರದ್ದಾಗುತ್ತದೆ.')),
              Q(W('What is the energy of a 500 nm photon in eV?', '500 nm फ़ोटॉन की ऊर्जा eV में कितनी है?', '500 nm ಫೋಟಾನ್‌ನ ಶಕ್ತಿ eV ಯಲ್ಲಿ ಎಷ್ಟು?'), W('About 2.48 eV (1240 ÷ 500).', 'लगभग 2.48 eV (1240 ÷ 500).', 'ಸುಮಾರು 2.48 eV (1240 ÷ 500).'))],
    )

